(() => {
  const ID = 'unbolt';
  const shell = () => window.TelePlayGameShell;
  const tg = window.Telegram?.WebApp;
  let screen, board, hint, scoreEl, bolts = [], moves = 0, score = 0, running = false, callbacks = {}, initialized = false, finished = false;
  const dependencies = [[1,2],[3],[3,4],[],[5],[]];
  const positions = [[18,20],[58,15],[32,43],[70,43],[15,70],[58,74]];
  const haptic = type => { try { tg?.HapticFeedback?.impactOccurred(type); } catch (_) {} };
  function render() { board.innerHTML = bolts.map((bolt, index) => { const blocked = bolt.removed || dependencies[index].some(dep => !bolts[dep].removed); return `<button type="button" class="unbolt-bolt ${blocked ? 'is-locked' : ''} ${bolt.removed ? 'is-removed' : ''}" style="left:${positions[index][0]}%;top:${positions[index][1]}%" data-unbolt="${index}" aria-label="Болт ${index + 1}">✦</button>`; }).join(''); scoreEl.textContent = score; }
  function remove(index) { if (!running || finished) return; const bolt = bolts[index], blocked = dependencies[index].some(dep => !bolts[dep].removed); if (bolt.removed) return; if (blocked) { hint.textContent = 'Этот болт держится на другом — сними опору первым'; score = Math.max(0, score - 15); haptic('heavy'); render(); return; } bolt.removed = true; moves += 1; score += Math.max(40, 150 - moves * 8); hint.textContent = 'Механическое напряжение перераспределено'; haptic('light'); render(); if (bolts.every(item => item.removed)) finish(); }
  function finish() { finished = true; const previous = shell().getStats(ID), result = shell().saveResult(ID, score, { bestMoves: previous.bestMoves ? Math.min(previous.bestMoves, moves) : moves, lastResult: { score, moves } }), reward = Math.max(1, Math.floor(score / 120)); window.TelePlayCore?.RewardManager?.award(ID, { coins: reward, score, metadata: { transactionId: `game:${ID}:run:${Date.now()}`, moves } }); shell().emit('unbolt_finished', { gameId: ID, score, moves, reward }); shell().emit('game_finished', { gameId: ID, score, reward, moves, victory: true }); shell().ResultScreen.show(screen.querySelector('[data-unbolt-result]'), { score, bestScore: result.bestScore, reward, newRecord: result.newRecord, title: 'Конструкция<br>разобрана!', details: { moves, bolts: '6 / 6' } }); screen.querySelector('[data-unbolt-result]').hidden = false; }
  function start() { bolts = Array.from({ length: 6 }, () => ({ removed: false })); moves = 0; score = 0; running = true; finished = false; screen.querySelector('[data-unbolt-start]').hidden = true; screen.querySelector('[data-unbolt-result]').hidden = true; shell().emit('unbolt_started', { gameId: ID }); shell().emit('game_started', { gameId: ID }); render(); haptic('light'); }
  function open(options = {}) { callbacks = options; screen.hidden = false; screen.querySelector('[data-unbolt-start]').hidden = false; screen.querySelector('[data-unbolt-result]').hidden = true; const stats = shell().getStats(ID); screen.querySelector('[data-unbolt-menu-best]').textContent = Number(stats.bestScore || 0).toLocaleString('ru-RU'); start(); screen.querySelector('[data-unbolt-start]').hidden = false; try { tg?.requestFullscreen?.(); tg?.disableVerticalSwipes?.(); } catch (_) {} }
  function hide() { running = false; screen.hidden = true; try { tg?.enableVerticalSwipes?.(); tg?.exitFullscreen?.(); } catch (_) {} }
  function close() { hide(); callbacks.onHome?.(); }
  function init() { if (initialized) return; initialized = true; screen = document.getElementById('unboltScreen'); screen.innerHTML = `<div class="unbolt-inner"><header class="unbolt-hud"><button class="icon-button" data-unbolt-close aria-label="На главную">×</button><div class="unbolt-brand"><small>TELEPLAY · ЛОГИКА</small><b>Unbolt</b></div><div class="unbolt-stat"><small>СЧЁТ</small><b data-unbolt-score>0</b></div><button class="icon-button" data-unbolt-reset aria-label="Начать заново">↻</button></header><div class="bolt-board" data-unbolt-board></div><p class="unbolt-hint" data-unbolt-hint>Сними болты в правильной последовательности</p></div><div class="start-panel" data-unbolt-start><span class="panel-kicker">TELEPLAY · ЛОГИКА</span><h2>Unbolt</h2><p>Освободи конструкцию.<br>Сначала сними опорные болты.</p><button class="play-button large" data-unbolt-start-button>Начать разбор</button><div class="record">Лучший результат: <b data-unbolt-menu-best>0</b></div></div><div class="start-panel result-panel" data-unbolt-result hidden><span class="panel-kicker" data-result="kicker">КОНСТРУКЦИЯ СВОБОДНА</span><h2 data-result="title">Конструкция<br>разобрана!</h2><div class="result-score"><small>РЕЗУЛЬТАТ</small><b data-result="score">0</b></div><div class="result-details"><span>Лучший результат <b data-result="best">0</b></span><span>Получено <b data-result="reward">+0 🪙</b></span><span>Ходы <b data-result="moves">0</b></span><span>Болты <b data-result="bolts">0 / 6</b></span></div><button class="play-button large" data-unbolt-replay>Новый разбор</button><button class="text-button" data-unbolt-home>На главную</button></div>`; board = screen.querySelector('[data-unbolt-board]'); hint = screen.querySelector('[data-unbolt-hint]'); scoreEl = screen.querySelector('[data-unbolt-score]'); board.addEventListener('click', event => { const bolt = event.target.closest('[data-unbolt]'); if (bolt) remove(Number(bolt.dataset.unbolt)); }); screen.querySelector('[data-unbolt-start-button]').addEventListener('click', start); screen.querySelector('[data-unbolt-replay]').addEventListener('click', start); screen.querySelector('[data-unbolt-home]').addEventListener('click', close); screen.querySelector('[data-unbolt-close]').addEventListener('click', close); screen.querySelector('[data-unbolt-reset]').addEventListener('click', start); start(); screen.querySelector('[data-unbolt-start]').hidden = false; }
  window.UnboltGame = { init, open, hide, close, start, restart: start, destroy: hide };
  document.readyState === 'loading' ? document.addEventListener('DOMContentLoaded', init) : init();
})();
